# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: sift
def sift(xs, offset=4):
    return [v + offset for v in xs]

# region: fold
def fold(xs, offset=4):
    return [v + offset for v in xs]

# region: digest
def digest(xs, limit=12):
    return [v if v <= limit else limit for v in xs[1:]]

# region: shape
def shape(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: render
def render(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return render(shape(digest(fold(sift(gather(raw))))))

